import XCTest
@testable import Sidra

/// The app API shapes (docs/app-api.md) decode, including dates and a machine agent whose project is only an id.
final class SubstrateTests: XCTestCase {
    func test_sessions() throws {
        let json = #"{"sessions": [{"id": "s1", "name": "Usman", "projects": [{"id": "p1", "name": "Messy", "handle": "messy", "agent": "Claude Code", "state": "blocked", "icon_url": null}, {"id": "p4", "name": "Inbox2", "handle": "inbox2", "agent": "Claude Code", "state": "working", "icon_url": null}, {"id": "p6", "name": "Pushleft", "handle": "pushleft", "agent": "Claude Code", "state": "idle", "icon_url": null}], "permissions": {"replies": true, "deploys": true, "files": true, "no_approval": false, "deploy_test": true, "deploy_production": false}, "waiting": 1, "last_used_at": "2026-11-19T23:23:01.853408Z", "expires_at": "2026-12-19T00:00:00Z", "active": true, "web_url": "https://substrate.gliph.sh/sessions/s1"}, {"id": "s2", "name": "Sarah", "projects": [{"id": "p2", "name": "Tuli", "handle": "tuli", "agent": "Claude Code", "state": "idle", "icon_url": null}], "permissions": {"replies": true, "deploys": true, "files": true, "no_approval": false, "deploy_test": true, "deploy_production": false}, "waiting": 0, "last_used_at": "2026-11-19T23:11:01.853408Z", "expires_at": "2026-12-12T00:00:00Z", "active": true, "web_url": "https://substrate.gliph.sh/sessions/s2"}, {"id": "s3", "name": "Ana", "projects": [{"id": "p5", "name": "Gluon", "handle": "gluon", "agent": "Claude Code", "state": "working", "icon_url": null}], "permissions": {"replies": true, "deploys": true, "files": true, "no_approval": false, "deploy_test": true, "deploy_production": false}, "waiting": 0, "last_used_at": "2026-11-18T23:25:01.853408Z", "expires_at": "2027-01-03T00:00:00Z", "active": true, "web_url": "https://substrate.gliph.sh/sessions/s3"}, {"id": "s4", "name": "Design team", "projects": [{"id": "p7", "name": "Gliph", "handle": "gliph", "agent": "Claude Code", "state": "idle", "icon_url": null}], "permissions": {"replies": true, "deploys": true, "files": true, "no_approval": false, "deploy_test": true, "deploy_production": false}, "waiting": 0, "active": false, "web_url": "https://substrate.