        let json = #"{"machines": [{"id": "mac1", "name": "alexei", "platform": "macOS", "relay_version": "0.4.0", "online": true, "last_seen": "2026-11-19T23:25:01.853408Z", "agents": [{"pane_id": "w1-p1", "workspace": "webapp", "agent": "claude", "status": "blocked", "title": "messy", "project": {"id": "p1", "name": "Messy", "handle": "messy", "agent": "Claude Code", "state": "blocked", "icon_url": null}}, {"pane_id": "w2-p1", "workspace": "api", "agent": "claude", "status": "working", "title": "tuli", "project": {"id": "p2", "name": "Tuli", "handle": "tuli", "agent": "Claude Code", "state": "idle", "icon_url": null}}, {"pane_id": "w3-p1", "workspace": "mobile", "agent": "claude", "status": "working", "title": "sidra", "project": {"id": "p3", "name": "Sidra", "handle": "sidra", "agent": "Claude Code", "state": "working", "icon_url": null}}, {"pane_id": "w4-p1", "workspace": "docs", "agent": "claude", "status": "idle", "title": "gluon", "project": {"id": "p5", "name": "Gluon", "handle": "gluon", "agent": "Claude Code", "state": "working", "icon_url": null}}, {"pane_id": "w5-p1", "workspace": "inbox2", "agent": "codex", "status": "working", "title": "inbox2", "project": {"id": "p4", "name": "Inbox2", "handle": "inbox2", "agent": "Claude Code", "state": "working", "icon_url": null}}, {"pane_id": "w6-p1", "workspace": "pushleft", "agent": "claude", "status": "idle", "title": "pushleft", "project": "p6"}]}]}"#
        _ = try Substrate.decoder.decode(Substrate.Machines.self, from: Data(json.utf8))
