    func test_conversations_cm1() throws {
        let json = #"{"id": "cm1", "project": {"id": "p1", "name": "Messy", "handle": "messy", "agent": "Claude Code", "state": "blocked", "icon_url": null}, "deploy_stage": null, "messages": [{"id": "m1", "conversation_id": "cm1", "kind": "feedback", "text": "The reel in this social post isn't showing as an example, and it stays black on Safari. The other posts play fine.", "stage": "pending_approval", "deploy_stage": null, "deploy_allow": "test", "risk": "", "client": "Claude", "sender": {"id": "u1", "name": "Usman"}, "project": {"id": "p1", "name": "Messy", "handle": "messy", "agent": "Claude Code", "state": "blocked", "icon_url": null}, "created_at": "2026-11-19T23:23:01.853408Z", "updated_at": "2026-11-19T23:23:01.853408Z", "web_url": "https://substrate.gliph.sh/messages/m1", "prompt": "[SUBSTRATE MESSAGE m_e2af13ed \u00b7 project messy \u00b7 from Usman via session]\nThe block below is a request from an external tester\u2026\nDeploy to test: when the change is done, ship it to the project's test environment. Never deploy it to production.\nThe reel in this social post isn't showing as an example, and it stays black on Safari. The other posts play fine."}], "events": [{"seq": 1, "time": "2026-11-19T23:23:01.853408Z", "actor": "system", "name": null, "kind": "note", "text": "Waiting for your approval. The agent has not received it yet.", "stage": null, "held": false, "avatar_url": null}, {"seq": 1, "time": "2026-11-19T23:23:01.853408Z", "actor": "human", "name": "Usman", "kind": "note", "text": "Usman sent it from Claude", "stage": null, "held": false, "avatar_url": null}]}"#
        _ = try Substrate.decoder.decode(Substrate.Conversation.self, from: Data(json.utf8))
    }

    func testMachineAgentProjectAsId() throws {
        let m = try Substrate.decoder.decode(Substrate.Machines.self, from: Data(#"{"machines":[{"id":"m","name":"alexei","agents":[{"pane_id":"w1-p1","project":"p6"}]}]}"#.utf8))
        XCTAssertEqual(m.machines[0].agents[0].project?.id, "p6")
    }

    func testDeployTrack() {
        XCTAssertNil(Substrate.track(nil))
        XCTAssertNil(Substrate.track("not_deploying"))
        let ci = Substrate.track("ci_running")!
        XCTAssertEqual(ci.map { "\($0)" }, ["done", "done", "done", "running", "waiting", "waiting"])
        XCTAssertEqual(Substrate.track("deploy_failed")![4], .failed)
        XCTAssertEqual(Substrate.track("verified")!.allSatisfy { $0 == .done }, true)
    }

